    ) {
        override fun toString(): kotlin.String = value

        /** The values the contract names. */
        public companion object {
            /** The provider rate limited the run (429). The run is over; after a short wait start a new run. */
            public val RateLimited: AgentErrorCode = AgentErrorCode("rate-limited")

            /** The organization has no AI provider credential configured, so no turn can run. */
            public val AiProviderNotConfigured: AgentErrorCode = AgentErrorCode("ai-provider-not-configured")

            /** A provider call failed with a message safe to show; the run stopped. */
            public val ProviderFailed: AgentErrorCode = AgentErrorCode("provider-failed")

            /** A fault other than a provider call ended the run; the message is a fixed generic line carrying no internal detail. */
            public val RunFailed: AgentErrorCode = AgentErrorCode("run-failed")

            /** The model repeated the same tool call with the same arguments after being told to change approach, so the run stopped rather than spending its budget on a loop. */
            public val Looping: AgentErrorCode = AgentErrorCode("looping")

            /** The member who started the run holds no write role in the organization it acts in, or that organization does not hold Map Studio, so the run stopped before its next turn. */
            public val AccessRevoked: AgentErrorCode = AgentErrorCode("access-revoked")
        }
    }

